  color: var(--text-muted);
  margin-bottom: 2rem;
}

.form-field {
  margin-bottom: 1.5rem;
  display: flex;
  flex-direction: column;
}

label {
  font-weight: 500;
  margin-bottom: 0.25rem;
  display: flex;
  justify-content: space-between;
}

.required-indicator {
  color: var(--error-color);
  font-size: 0.875rem;
}

