', direction=None, fact=None, file_name='/workspace/sandbox/variants/accessible_basic/simple-contact-form--framework-react--style-modern--validation-message-present/google/gemini-3-flash-preview__s4/app.js', full_command_text=None, has_write_file_redirection=None, hook_message=None, intention='Edit file', new_file_contents='const { useState, useRef } = React;

const FormField = ({ label, id, type = "text", required, optional, helperText, error, value, onChange }) => {
  return (
    <div className="form-field">
      <label htmlFor={id}>
        {label}
        {required && <span className="required-indicator" aria-hidden="true">*</span>}
      </label>
      <input
        id={id}
        name={id}
        type={type}
        required={required}
        aria-required={required}
        aria-invalid={!!error}
        aria-describedby={`${id}-desc ${error ? `${id}-error` : ""}`.trim()}
        value={value}
        onChange={onChange}
      />
      <div id={`${id}-desc`} className="helper-text">
        {helperText}
      </div>
      <div 
        id={`${id}-error`} 
        className="error-message" 
        role="alert" 
        aria-live="polite"
      >
        {error}
      </div>
    </div>
  );
};

const ContactForm = () => {
  const [formData, setFormData] = useState({
    fullName: "",
    email: "",
    phone: ""
  });
  const [errors, setErrors] = useState({});
  const [submitted, setSubmitted] = useState(false);

  const nameRef = useRef(null);
  const emailRef = useRef(null);
  const phoneRef = useRef(null);

  const validate = () => {
    const newErrors = {};
    if (!formData.fullName.trim()) {
      newErrors.fullName = "Full name is required.";
    }

    if (!formData.email.trim()) {
      newErrors.email = "Email address is required.";
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
      newErrors.email = "Please enter a valid email address.";
    }

    // Phone is optional, but if we wanted to validate format we could.
    // The requirement says helper text describes the format.
    // Let's assume some basic validation if provided, or just leave it since it's optional.

    return newErrors;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const newErrors = validate();
    setErrors(newErrors);

    if (Object.keys(newErrors).length > 0) {
      // Focus the first invalid control
      if (newErrors.fullName) {
        document.getElementById("fullName").focus();
      } else if (newErrors.email) {
        document.getElementById("email").focus();
      }
      return;
    }

    // Success
    setSubmitted(true);
    console.log("Form submitted:", formData);
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
    // Clear error when user types
    if (errors[name]) {
      setErrors(prev => {
        const next = { ...prev };
        delete next[name];
        return next;
      });
    }
  };

  if (submitted) {
    return (
      <div className="success-message" role="alert">
        <h2>Thank you!</h2>
        <p>Your support request has been submitted successfully.</p>
        <button onClick={() => setSubmitted(false)}>Send another message</button>
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} noValidate>
      <h1>Contact Support</h1>
      <p className="subtitle">We'll get back to you as soon as possible.</p>

      <FormField
        id="fullName"
        label="Full Name"
        required
        value={formData.fullName}
        onChange={handleChange}
        error={errors.fullName}
      />

      <FormField
        id="email"
        label="Email Address"
        type="email"
        required
        value={formData.email}
        onChange={handleChange}
        error={errors.email}
      />

      <FormField
        id="phone"
        label="Phone Number (optional)"
        optional
        helperText="Format: (123) 456-7890"
        value={formData.phone}
        onChange={handleChange}
        error={errors.phone}
      />

      <button type="submit">Submit Request</button>
    </form>
  );
};

const App = () => {
  return (
    <main>
      <ContactForm />
    </main>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
